SELECT USER_ACTIVITY_ID, USER_ID, USER_ACTIVITY_TYPE, USER_ACTIVITY_TIME, USER_ACTIVITY_TARGET_ID, USER_ACTIVITY_TARGET_TYPE, USER_ACTIVITY_DETAILS
FROM user_activity
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT USER_ACTIVITY_ID, USER_ID, USER_ACTIVITY_TYPE, USER_ACTIVITY_TIME, USER_ACTIVITY_TARGET_ID, USER_ACTIVITY_TARGET_TYPE, USER_ACTIVITY_DETAILS
FROM user_activity
WHERE USER_ACTIVITY_ID = #{activityId}

SELECT USER_ACTIVITY_ID, USER_ID, USER_ACTIVITY_TYPE, USER_ACTIVITY_TIME, USER_ACTIVITY_TARGET_ID, USER_ACTIVITY_TARGET_TYPE, USER_ACTIVITY_DETAILS
FROM user_activity
WHERE USER_ID = #{UserId}
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT USER_ACTIVITY_ID, USER_ID, USER_ACTIVITY_TYPE, USER_ACTIVITY_TIME, USER_ACTIVITY_TARGET_ID, USER_ACTIVITY_TARGET_TYPE, USER_ACTIVITY_DETAILS
FROM user_activity


        AND USER_ID = #{userActivitySearchDTO.user_id}


        AND USER_ACTIVITY_TYPE LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_type}, '%')


        AND (
        user_activity_target_id LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_target}, '%')
        OR USER_ACTIVITY_TARGET_TYPE LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_target}, '%')
        )


        AND USER_ACTIVITY_TIME >= #{userActivitySearchDTO.user_activity_time_start}


        AND USER_ACTIVITY_TIME <= #{userActivitySearchDTO.user_activity_time_end}


        AND USER_ACTIVITY_DETAILS LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_details}, '%')


ORDER BY USER_ACTIVITY_TIME DESC
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT COUNT(*)
FROM user_activity


        AND USER_ID = #{userActivitySearchDTO.user_id}


        AND USER_ACTIVITY_TYPE LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_type}, '%')


        AND (
        user_activity_target_id LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_target}, '%')
        OR USER_ACTIVITY_TARGET_TYPE LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_target}, '%')
        )


        AND USER_ACTIVITY_TIME >= #{userActivitySearchDTO.user_activity_time_start}


        AND USER_ACTIVITY_TIME <= #{userActivitySearchDTO.user_activity_time_end}


        AND USER_ACTIVITY_DETAILS LIKE CONCAT('%', #{userActivitySearchDTO.user_activity_details}, '%')
